function Login({onLogin,onStart,loadError}:{onLogin:()=>Promise<void>;onStart:()=>void;loadError:string}){
 const[email,setEmail]=useState(''),[password,setPassword]=useState(''),[demo,setDemo]=useState(false),[error,setError]=useState(''),[busy,setBusy]=useState(false);
 useEffect(()=>{api<{demo:boolean}>('/config').then(c=>setDemo(c.demo)).catch(()=>setError('El servidor de Aros no está disponible.'))},[]);
 async function submit(isDemo=false){if(busy)return;onStart();setBusy(true);setError('');try{await api('/auth/'+(isDemo?'demo':'login'),json('POST',isDemo?{}:{email,password}));await onLogin()}catch(e){setError((e as Error).message)}finally{setBusy(false)}}
 return <div className="login"><div className="login-panel"><Orb size={52}/><h1>Aros.</h1><p>Todo lo que importa.<br/>Un espacio para tenerlo bajo control.</p>{(error||loadError)&&<div className="error" role="alert">{error||loadError}</div>}<form onSubmit={e=>{e.preventDefault();void submit()}}><label className="field">Email<input autoComplete="username" type="text" value={email} onChange={e=>setEmail(e.target.value)} required/></label><label className="field">Contraseña<input autoComplete="current-password" type="password" value={password} onChange={e=>setPassword(e.target.value)} required/></label><button className="primary" disabled={busy}>{busy?<LoaderCircle size={16}/>:<ArrowUpRight size={16}/>}Entrar en Aros</button></form>{demo&&<button className="secondary demo-login" disabled={busy} onClick={()=>void submit(true)}><FlaskConical size={15}/>Explorar con datos de ejemplo</button>}<SourceNotice/></div></div>
}

